using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using StockFlow.Data;
using StockFlow.Models;
namespace StockFlow.Controllers; [Authorize] public class SalesController(ApplicationDbContext db) : Controller { public async Task<IActionResult> Index() => View(await db.Sales.OrderByDescending(s => s.SoldAt).Take(200).ToListAsync()); [Authorize(Roles = "Admin,Manager,StockClerk")] public async Task<IActionResult> Create() { ViewBag.Products = await db.Products.Where(p => p.IsActive && p.QuantityOnHand > 0).OrderBy(p => p.Name).ToListAsync(); return View(new CreateSaleVm { Quantity = 1 }); } [HttpPost, ValidateAntiForgeryToken, Authorize(Roles = "Admin,Manager,StockClerk")] public async Task<IActionResult> Create(CreateSaleVm vm) { var p = await db.Products.FindAsync(vm.ProductId); if (p == null || !p.IsActive) ModelState.AddModelError("", "Select a valid active product."); else if (vm.Quantity < 1 || vm.Quantity > p.QuantityOnHand) ModelState.AddModelError(nameof(vm.Quantity), "Quantity must be positive and cannot exceed available stock."); if (!ModelState.IsValid) { ViewBag.Products = await db.Products.Where(x => x.IsActive && x.QuantityOnHand > 0).ToListAsync(); return View(vm); } var sale = new Sale { SaleNumber = "SO-" + DateTime.UtcNow.ToString("yyyyMMddHHmmss") + Random.Shared.Next(10, 99), CustomerName = vm.CustomerName, RecordedBy = User.Identity?.Name ?? "unknown", Total = p!.SellingPrice * vm.Quantity }; sale.Lines.Add(new SaleLine { ProductId = p.Id, Quantity = vm.Quantity, UnitPrice = p.SellingPrice }); p.QuantityOnHand -= vm.Quantity; db.Sales.Add(sale); db.StockMovements.Add(new StockMovement { ProductId = p.Id, Type = MovementType.Sale, QuantityChange = -vm.Quantity, BalanceAfter = p.QuantityOnHand, Reason = "Sale recorded", Reference = sale.SaleNumber, PerformedBy = sale.RecordedBy }); db.AuditLogs.Add(new AuditLog { UserEmail = sale.RecordedBy, Action = "Sale recorded", EntityName = "Sale", EntityId = sale.SaleNumber, Details = $"Quantity {vm.Quantity}; total {sale.Total:C}" }); await db.SaveChangesAsync(); TempData["Success"] = "Sale recorded and stock reduced."; return RedirectToAction(nameof(Index)); } }
